-- =====================================================================
-- 03_load_data.sql
-- Ride-Sharing Analytics & Cancellation Prediction
-- Loads the CSVs generated by python/01_data_generation.ipynb into MySQL.
--
-- Run this AFTER 01_create_database.sql and 02_create_tables.sql, and
-- AFTER the data-generation notebook has populated data/raw/*.csv.
--
-- NOTE: LOAD DATA LOCAL INFILE requires the client and server to allow
-- local infile loading:
--   mysql --local-infile=1 -u root -p ride_sharing_analytics < sql/03_load_data.sql
-- and on the server side: SET GLOBAL local_infile = 1;
--
-- Adjust the absolute path below to wherever you cloned the repo.
-- =====================================================================

USE ride_sharing_analytics;

SET FOREIGN_KEY_CHECKS = 0;

LOAD DATA LOCAL INFILE 'data/raw/riders.csv'
INTO TABLE riders
FIELDS TERMINATED BY ',' ENCLOSED BY '"'
LINES TERMINATED BY '\n'
IGNORE 1 ROWS
(rider_id, first_name, last_name, email, phone, gender, age, city, signup_date, preferred_payment);

LOAD DATA LOCAL INFILE 'data/raw/drivers.csv'
INTO TABLE drivers
FIELDS TERMINATED BY ',' ENCLOSED BY '"'
LINES TERMINATED BY '\n'
IGNORE 1 ROWS
(driver_id, first_name, last_name, email, phone, gender, city, license_number, signup_date, driver_status, avg_rating);

LOAD DATA LOCAL INFILE 'data/raw/vehicles.csv'
INTO TABLE vehicles
FIELDS TERMINATED BY ',' ENCLOSED BY '"'
LINES TERMINATED BY '\n'
IGNORE 1 ROWS
(vehicle_id, driver_id, vehicle_type, make, model, year, plate_number, seating_capacity);

LOAD DATA LOCAL INFILE 'data/raw/locations.csv'
INTO TABLE locations
FIELDS TERMINATED BY ',' ENCLOSED BY '"'
LINES TERMINATED BY '\n'
IGNORE 1 ROWS
(location_id, city, area_name, latitude, longitude);

LOAD DATA LOCAL INFILE 'data/raw/trips.csv'
INTO TABLE trips
FIELDS TERMINATED BY ',' ENCLOSED BY '"'
LINES TERMINATED BY '\n'
IGNORE 1 ROWS
(trip_id, rider_id, driver_id, vehicle_id, pickup_location_id, drop_location_id,
 request_datetime, pickup_datetime, drop_datetime, distance_km, duration_min,
 base_fare, surge_multiplier, fare_amount, trip_status, cancellation_reason, payment_method);

LOAD DATA LOCAL INFILE 'data/raw/payments.csv'
INTO TABLE payments
FIELDS TERMINATED BY ',' ENCLOSED BY '"'
LINES TERMINATED BY '\n'
IGNORE 1 ROWS
(payment_id, trip_id, amount, payment_method, payment_status, payment_datetime);

LOAD DATA LOCAL INFILE 'data/raw/ratings.csv'
INTO TABLE ratings
FIELDS TERMINATED BY ',' ENCLOSED BY '"'
LINES TERMINATED BY '\n'
IGNORE 1 ROWS
(rating_id, trip_id, rider_rating_for_driver, driver_rating_for_rider, feedback_text);

SET FOREIGN_KEY_CHECKS = 1;

SELECT 'riders'    AS table_name, COUNT(*) AS row_count FROM riders
UNION ALL SELECT 'drivers',   COUNT(*) FROM drivers
UNION ALL SELECT 'vehicles',  COUNT(*) FROM vehicles
UNION ALL SELECT 'locations', COUNT(*) FROM locations
UNION ALL SELECT 'trips',     COUNT(*) FROM trips
UNION ALL SELECT 'payments',  COUNT(*) FROM payments
UNION ALL SELECT 'ratings',   COUNT(*) FROM ratings;
